	/* Check for intelligence report.
	 *
	 * Once per pass through events(), not once per move: a single warp
	 * jump can schedule the Super-commander's move more than once, and
	 * each of those rolled the 20% again and printed the same two
	 * lines. Reading the same sentence twice in a row does not look
	 * like two reports, it looks like the game stuttering.
	 *
	 * The starch test below was meant to stop that -- don't report
	 * what is already on the chart -- but printing the report never
	 * marks the chart, so it could never become true by having
	 * reported. Marking it would be the other fix, and a bigger one:
	 * the chart shows what a quadrant holds, and the report says only
	 * where the Super-commander is. */
	if (*irep) return;
	if (
#ifdef DEBUG
		idebug==0 &&
#endif
		(Rand() > 0.2 ||
		 (!REPORTS) ||
		 starch[d.isx][d.isy] > 0))
		return;
	if (*ipage==0) pause(1);
	*ipage = 1;
	*irep = 1;
	prout("Lt. Uhura-  \"Captain, Starfleet Intelligence reports");
	proutn("   the Super-commander is in");
	cramlc(1, d.isx, d.isy);
	prout(".\"");
	return;

