10	/* The condition the ship is in, worked out without writing it down.
11	 *
12	 * newcnd() stores the same answer in the global, which is fine when
13	 * the player asks for a scan between turns. The panel repaints in the
14	 * middle of one, and moving.c sets RED by hand before a tractor beam
15	 * takes hold -- a refresh that recomputed the global would hand that
16	 * back to GREEN just as the game decided the player was in trouble.
17	 * It lives here so the formatters stay testable on their own. */
18	int condition_now(void) {
19		if (d.galaxy[quadx][quady] > 99 || d.newstuf[quadx][quady] > 9)
20			return IHRED;
21		if (energy < 1000.0)
22			return IHYELLOW;
23		return IHGREEN;
24	}
