26	/* Classify a cell the panel is about to draw, by the character itself.
27	 *
28	 * Taking the character rather than the quadrant contents is what keeps
29	 * colour honest: a cell the sensors are hiding has already become '-'
30	 * by the time it gets here, so there is nothing left to leak. */
31	int cell_class(char c) {
32		switch (c) {
33			case IHK: case IHC: case IHS: case IHR: case IHT:
34				return CELL_HOSTILE;
35			case IHE: case IHF:	return CELL_SHIP;
36			case IHB:		return CELL_BASE;
37			case IHSTAR:		return CELL_STAR;
38			case IHP:		return CELL_PLANET;
39			case IHWEB:		return CELL_WEB;
40			case IHQUEST:		return CELL_THING;
41			/* A black hole (IHBLANK) is deliberately absent: it shows as
42			   empty space on a short-range scan, which is the whole trap.
43			   Marking it would change what the game tells the player, not
44			   how it looks. */
45			case '-':		return CELL_HIDDEN;
46			default:		return CELL_PLAIN;
47		}
48	}
