50	/* Whether a status line is worth reading twice: the fields that tell a
51	 * player something is wrong, and the two that say it is not. */
52	int status_class(int i) {
53		switch (i) {
54			case 2:		/* condition */
55				if (condit == IHDOCKED) return STAT_DOCKED;
56				switch (condition_now()) {
57					case IHRED:	return STAT_BAD;
58					case IHYELLOW:	return STAT_WARN;
59					default:	return STAT_GOOD;
60				}
61			case 4:		/* life support */
62				if (damage[DLIFSUP] == 0.0) return STAT_GOOD;
63				return condit == IHDOCKED ? STAT_WARN : STAT_BAD;
64			case 8:		/* shields */
65				if (damage[DSHIELD] != 0) return STAT_BAD;
66				return shldup ? STAT_GOOD : STAT_WARN;
67			case 10:	/* time left */
68				/* The one number nothing else warns about: running the
69				   clock out loses the game, and no event or line of
70				   prose ever mentions it approaching. */
71				if (intime <= 0.0) return STAT_PLAIN;
72				if (d.remtime < 0.10*intime) return STAT_BAD;
73				if (d.remtime < 0.20*intime) return STAT_WARN;
74				return STAT_PLAIN;
75			default:
76				return STAT_PLAIN;
77		}
78	}
