59	static chtype attr_for_cell(char c) {
60		if (!use_colour) return A_NORMAL;
61		switch (cell_class(c)) {
62			case CELL_HOSTILE:	return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
63			/* The ship takes no colour pair on purpose: bold alone keeps
64			   the terminal's own foreground, so it stands out on a light
65			   background as surely as on a dark one. A hardcoded white
66			   would be invisible on the former. */
67			case CELL_SHIP:		return A_BOLD;
68			case CELL_BASE:		return COLOR_PAIR(CP_BASE) | A_BOLD;
69			/* Stars are the most numerous thing on the grid and the least
70			   worth looking at, so they stay quiet -- and yellow is spoken
71			   for by the status panel, where it means caution. */
72			case CELL_STAR:		return COLOR_PAIR(CP_STAR);
73			case CELL_PLANET:	return COLOR_PAIR(CP_PLANET);
74			case CELL_WEB:		return COLOR_PAIR(CP_THING);
75			case CELL_THING:	return COLOR_PAIR(CP_THING) | A_BOLD;
76			case CELL_HIDDEN:	return A_DIM;
77			default:		return A_NORMAL;
78		}
