83		switch (status_class(line)) {
84			case STAT_GOOD:		return COLOR_PAIR(CP_GOOD);
85			case STAT_WARN:		return COLOR_PAIR(CP_WARN);
86			case STAT_BAD:		return COLOR_PAIR(CP_HOSTILE) | A_BOLD;
87			case STAT_DOCKED:	return COLOR_PAIR(CP_BASE) | A_BOLD;
