120	/* Whether this terminal can actually run the full-screen interface.
121	 *
122	 * initscr() is no good for asking: given a TERM it doesn't know it
123	 * prints an error and exits the process, taking the game with it. Worse
124	 * is a terminal it does know but that cannot address the cursor -- TERM
125	 * =dumb, which is what Emacs' shell buffer sets. There curses starts
126	 * happily and then draws nothing usable, so the game looks hung.
127	 *
128	 * setupterm() reports both cases instead of exiting. The answer is
129	 * cached because main() asks again to word the fallback notice. */
130	int tui_terminal_capable(void) {
131		static int checked = FALSE, capable = FALSE;
132		char *cup;
133		int err;
134	
135		if (checked) return capable;
136		checked = TRUE;
137		if (setupterm(NULL, fileno(stdout), &err) == ERR)
138			return capable;		/* no such terminal type */
139		cup = tigetstr("cup");
140		capable = cup != NULL && cup != (char *)-1;
141		return capable;
142	}
