void tui_puts(char *s) {
	waddstr(wmsg, s);
	wrefresh(wmsg);
}

void tui_puts_slow(char *s) {
	while (*s) {
		waddch(wmsg, *s++);
		wrefresh(wmsg);
		napms(30);
