/* The size the windows were last built for, so a read that comes back
 * empty can be told apart from one interrupted by the terminal
 * changing shape. */
static int builtlines, builtcols;

/* Lay the three windows out for the terminal as it is now. Called
 * again after a resize, so it deletes what was there first.
 *
 * A terminal that has shrunk below the 72x24 the display asks for at
 * startup is not torn down mid-game: the panels keep their size and
 * the screen clips, which is ugly but leaves the player where they
 * were. Ending curses under them to say the window is too small would
 * be a worse answer to a mouse drag. */
static void make_windows(void) {
	int msgh;

	if (wquad != NULL) delwin(wquad);
	if (wstat != NULL) delwin(wstat);
	if (wmsg != NULL) delwin(wmsg);
	builtlines = LINES;
	builtcols = COLS;
	msgh = LINES-PANELH;
	if (msgh < 1) msgh = 1;
	wquad = newwin(PANELH, QUADW, 0, 0);
	wstat = newwin(PANELH, COLS-QUADW > 1 ? COLS-QUADW : 1, 0, QUADW);
	wmsg = newwin(msgh, COLS-2 > 1 ? COLS-2 : 1, PANELH, 1);
	scrollok(wmsg, TRUE);
	keypad(wmsg, TRUE);
}

/* Whether the terminal changed shape since the windows were built.
 * curses updates LINES and COLS for us before it reports the resize;
 * all this has to notice is that they no longer match. */
static int resized(void) {
	return LINES != builtlines || COLS != builtcols;
}

/* Rebuild for the new size and redraw. The message window's contents
 * are lost -- curses has no way to reflow them and the game keeps no
 * transcript -- so the panels come back and the conversation carries
 * on from wherever it had got to. */
static void take_resize(void) {
	make_windows();
	clearok(stdscr, TRUE);
	wrefresh(curscr);
	tui_refresh_panels();
}

